// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address originalCeo) public {
        vm.assume(originalCeo != address(0));
        vm.assume(caller == originalCeo);
        // Set initial ceoAddress to originalCeo by pranking as the deployer
        vm.startPrank(originalCeo);
        c.DrugDealer();
        vm.stopPrank();

        address ceoBefore = c.ceoAddress();
        require(ceoBefore == originalCeo, "setup failed");

        vm.prank(caller);
        c.DrugDealer();

        address ceoAfter = c.ceoAddress();
        assertTrue(ceoAfter == ceoBefore);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address public originalCEO;

    function setUp() public {
        c = new C();
        originalCEO = c.ceoAddress();
    }

    function testFuzz_property(address caller) public {
        // 1. Caller must not be the original CEO, so we test permission logic.
        vm.assume(caller != originalCEO);

        // 2. Prank as the caller who is NOT the original CEO.
        vm.prank(caller);
        try c.DrugDealer() {} catch {}

        // 3. After the call, ceoAddress must remain the originalCEO (since caller was not CEO).
        //    The reference keeps it unchanged, the mutant changes it to a fixed address.
        assertEq(c.ceoAddress(), originalCEO);
    }
}
